const report = $input.first().json;
const workflow = $('Read Current Staging Handler').first().json;
const nodes = Object.fromEntries(workflow.nodes.map(n => [n.name, n]));
const results = [];
function run(name, ctx, input = {}) {
  const dollar = n => {
    if (!(n in ctx)) throw new Error('Unexecuted node: ' + n);
    const data = Array.isArray(ctx[n]) ? ctx[n] : [ctx[n]];
    return { first: () => ({ json: data[0] }), all: () => data.map(json => ({ json })) };
  };
  const values = Array.isArray(input) ? input : [input];
  return new Function('$', '$input', nodes[name].parameters.jsCode)(dollar, { first: () => ({ json: values[0] }), all: () => values.map(json => ({ json })) });
