const cfg = { liveMode: false, calendlyUtmSource: 'uxr_recruiting' };
const base = { 'Load Session': row, 'Load Config (Send)': cfg, 'Load Config (Email)': cfg, 'Load Config (Approve)': cfg, 'Calendly Membership': {}, 'Calendly Event Types': {} };
