  assert('Unticked: no bcc', send(false).bcc_email === '' && send(false).bcc_me === false);
  assert('Card without the checkbox: no bcc', send(false, row, { values: {} }).bcc_email === '');
  assert('No Slack email: no bcc even when ticked', send(true, { ...row, slack_user_email: '' }).bcc_email === '');
});
