// ---- Edited list after "Remove candidates"
function editFlow(prep, result, audience, keep) {
  const first = card(prep, result);
  const rows = first.candidates.map((c, i) => ({ id: 100 + i, batch_id: first.batch_id, status: 'staged', email: c.email, summary: c.summary, attributes_json: JSON.stringify(c) }));
  const session = { session_key: 'test-only', batch_id: first.batch_id, audience };
  const open = blocks => run('Build Remove Modal', { 'Parse Payload': click({ full_payload: { message: { blocks } } }), 'Load Session': session }, rows)[0].json.view.private_metadata;
  const render = (meta, n) => run('Render Edited Candidates', { 'Parse Payload': { channel_id: 'TEST', full_payload: { view: { private_metadata: meta } } }, 'Load Session': session }, rows.slice(0, n))[0].json;
  const meta = open(parse(first.blocks));
  const edited = render(meta, keep);
  return { meta, edited, text: texts(edited.blocks), again: open(edited.blocks), render };
}
check('Edited list (CSV): summary kept, note recomputed', assert => {
  const f = editFlow(csvPrep, csvResult(), 'csv', 1);
  assert('Title shows what is left', f.text.includes('(1 selected)'));
