  assert('Note recomputed on the remaining rows', f.text.includes('1 person has another Customer.io profile'));
  assert('Row marker kept', f.text.includes('one profile unsubscribed'));
  assert('A second removal still carries the summary', typeof JSON.parse(f.again).summary === 'string');
  assert('Note disappears when nobody left has such a twin', !texts(f.render(f.meta, 0).blocks).includes('another Customer.io profile'));
});
