// Rules of UXR Search and UXR Send & Stamp, checked on the code currently on staging (added 2026-10-08, replaces the local test files).
// Runs their Code nodes with fixtures and a fixed clock. No Customer.io call, no email, no table write.
const report = $('Handler Checks: BCC and Candidate Card').first().json;
const searchWf = $('Read Current Staging Search').first().json;
const sendWf = $input.first().json;
if (searchWf.id !== '6uEc2xCDjqeG0OJt' || sendWf.id !== 'pTYT5A34Hv5CplJX') throw new Error('Expected the staging UXR Search and UXR Send & Stamp definitions');
const code = { search: Object.fromEntries(searchWf.nodes.map(n => [n.name, n.parameters.jsCode])), send: Object.fromEntries(sendWf.nodes.map(n => [n.name, n.parameters.jsCode])) };
const NOW = Date.parse('2026-09-24T10:00:00Z');
const RealDate = Date;
class Clock extends RealDate { constructor(...args) { super(...(args.length ? args : [NOW])); } static now() { return NOW; } }
const clone = v => JSON.parse(JSON.stringify(v === undefined ? null : v));
function run(wf, node, { input = [], refs = {} } = {}) {
  if (!code[wf][node]) throw new Error('Missing node: ' + wf + '/' + node);
  const acc = values => ({ first: () => ({ json: clone(values[0]) }), all: () => values.map(json => ({ json: clone(json) })) });
  const dollar = name => { if (!(name in refs)) throw new Error('Missing fixture for node ' + name); return acc(refs[name]); };
  const out = new Function('$', '$input', 'Date', code[wf][node])(dollar, acc(input), Clock);
  return clone(out).map(item => item.json);
}
const results = [];
function check(name, fn) {
  const checks = [];
  const assert = (label, ok) => checks.push({ name: label, status: ok ? 'PASS' : 'FAIL' });
  try { fn(assert); } catch (e) { assert('No exception: ' + e.message, false); }
  results.push({ name, checks, status: checks.every(c => c.status === 'PASS') ? 'PASS' : 'FAIL' });
}
const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);

// Search fixture. Profiles are plain attribute objects; switches: sibling (in Customer.io but not returned by the search), uploaded (a sibling
// whose email was in the CSV), inCooldownSegment, fetchError, topLevelUnsubscribed. The four per-person nodes run in their real order.
function format(profiles, { mode = 'csv', lookupStatus = 200, sampleSize = 10, extraUploaded = [], filters = {}, extraConfig = {} } = {}) {
  const key = e => String(e || '').trim().toLowerCase();
  const all = profiles.map((p, i) => ({ ...p, cio_id: 'fixture-' + i }));
  const strip = ({ sibling, uploaded, inCooldownSegment, fetchError, topLevelUnsubscribed, cio_id, ...attrs }) => attrs;
  const response = p => p.fetchError ? { error: 'fixture failure' } : { customer: { attributes: strip(p), unsubscribed: p.topLevelUnsubscribed === undefined ? false : p.topLevelUnsubscribed } };
  const sampled = all.filter(p => !p.sibling);
  const samples = sampled.map(p => ({ cio_id: p.cio_id, email: p.email }));
  const fetchedAttrs = sampled.map(response);
  const config = [{ cooldownSegmentId: '260', ...extraConfig }];
  const uploadedEmails = Array.from(new Set(all.filter(p => !p.sibling || p.uploaded).map(p => key(p.email)).concat(extraUploaded.map(key))));
  const state = { mode, csvMode: mode === 'csv', sampleSize, filters, cooldownCutoffTs: NOW / 1000 - 60 * 86400, collected: samples, collectedCount: samples.length, csvEmails: mode === 'csv' ? uploadedEmails : undefined };
  const lookups = run('search', 'Build Email Lookups', { input: fetchedAttrs, refs: { 'Sample Candidates': samples, 'Collect & Check': [state] } });
  const asked = new Set(lookups.flatMap(l => l.emails));
  const page = list => [{ statusCode: lookupStatus, body: { identifiers: list.map(p => ({ cio_id: p.cio_id, id: p.cio_id, email: p.email })) } }];
  const lookupPages = page(all.filter(p => asked.has(key(p.email))));
  const cooldownLookups = run('search', 'Build Cooldown Lookups', { refs: { 'Load Config': config, 'Build Email Lookups': lookups } });
  const cooldownPages = page(cooldownLookups.some(l => l.emails.length) ? all.filter(p => p.inCooldownSegment && asked.has(key(p.email))) : []);
  const picks = run('search', 'Pick Siblings', { refs: { 'Sample Candidates': samples, 'Fetch Attributes': fetchedAttrs, 'Lookup Profiles By Email': lookupPages } });
  const byId = new Map(all.map(p => [p.cio_id, p]));
  return run('search', 'Format Output', { input: picks.map(p => p.__none ? {} : response(byId.get(p.cio_id))), refs: {
    'Collect & Check': [state], 'Sample Candidates': samples, 'Fetch Attributes': fetchedAttrs, 'Load Config': config,
    'Lookup Profiles By Email': lookupPages, 'Lookup Cooldown By Email': cooldownPages, 'Pick Siblings': picks } })[0];
}
const count = (profiles, opts) => format(profiles, opts).candidates.length;
const email = 'same-person@example.test';
const recent = NOW / 1000 - 3600;

// ---- Send & Stamp
function validate(config = {}, caller = {}) {
  return run('send', 'Validate Send', { refs: { 'When Called': [{ batch_id: 'fixture-batch', email_body: 'Hello', ...caller }], 'Load Config': [{ testRecipient: 'test@example.test', ...config }] } })[0];
}
function recipients(staged, recentRows = [], config = {}) {
  return run('send', 'Prepare Recipients', { input: [], refs: { 'Validate Send': [{ ...validate({ liveMode: true }), ...config }], 'Get Staged Candidates': staged.map((r, i) => ({ id: i + 1, ...r })), 'Get Recently Sent': recentRows } });
}
check('Send: only liveMode true (boolean) allows real sends', assert => {
  for (const liveMode of [false, undefined, 'true', 1]) assert('liveMode ' + JSON.stringify(liveMode) + ' forces test mode', validate({ liveMode }).test_mode === true);
  assert('Boolean true permits live mode', validate({ liveMode: true }).test_mode === false);
  assert('Caller can force test mode when config is live', validate({ liveMode: true }, { test_mode: true }).test_mode === true);
});
check('Send: refuses incomplete input', assert => {
  assert('Missing batch', validate({}, { batch_id: '' }).valid === false);
  assert('Calendly placeholder without URL', validate({}, { email_body: 'Book: {{calendly_link}}' }).valid === false);
});
check('Send: one mailbox per row, cooldown from the Candidates table', assert => {
  assert('Two mailboxes in one row are skipped', recipients([{ email: 'a@example.test,b@example.test' }])[0].skip === true);
  for (const status of ['sent', 'booked']) assert('Recent ' + status + ' row blocks', recipients([{ email }], [{ email, status, [status === 'booked' ? 'booked_at' : 'sent_at']: new RealDate(NOW - 3600000).toISOString() }])[0].skip === true);
  assert('Old send does not block', recipients([{ email }], [{ email, status: 'sent', sent_at: new RealDate(NOW - 61 * 86400000).toISOString() }])[0].skip === false);
});
check('Send: test mode redirects and caps', assert => {
  const rows = recipients([1, 2, 3, 4].map(i => ({ email: 'person' + i + '@example.test' })), [], { test_mode: true, test_max: 3, test_recipient: 'test@example.test' });
  assert('Capped at 3', rows.length === 3);
  assert('All redirected and labelled', rows.every(r => r.recipient === 'test@example.test' && r.subject.startsWith('[TEST for ')));
});
check('Send: result recorded truthfully', assert => {
  const stamp = run('send', 'Record Result', { input: [{ statusCode: 500 }], refs: { 'Send Loop': [{ email, row_id: 1 }], 'Check Send OK': [{ email, row_id: 1, send_ok: true, test_mode: false, stamp_skipped: false }] } })[0];
  assert('Failed stamp keeps sent status and is reported', stamp.final_status === 'sent' && stamp.stamp_failed === true);
  const smtp = run('send', 'Record Result', { input: [{}], refs: { 'Send Loop': [{ email, row_id: 1 }], 'Check Send OK': [{ email, row_id: 1, send_ok: false, error: 'SMTP rejected' }] } })[0];
  assert('Failed SMTP stays failed with no timestamp', smtp.final_status === 'failed' && smtp.sent_at === '');
});
check('Send: BCC and first-name greeting', assert => {
  for (const v of [null, undefined, '', '   ']) { const r = validate({}, { bcc_email: v }); assert('bcc ' + JSON.stringify(v) + ' means no BCC', r.valid === true && r.bcc_email === ''); }
  const ok = validate({}, { bcc_email: ' me@n8n.io ' });
  assert('Valid bcc passes through trimmed', ok.valid === true && ok.bcc_email === 'me@n8n.io');
  for (const v of ['a@x.io,b@y.io', 'not-an-email', 'a@x.io; b@y.io', 'Name <a@x.io>']) assert('Malformed bcc refuses the run: ' + v, validate({}, { bcc_email: v }).valid === false);
  const v = { batch_id: 'b', email_subject: 'S', email_body: 'Hi {{first_name}},', calendly_url: '', test_mode: true, test_recipient: 't@example.test', test_max: 3, cooldown_days: 60 };
  const prep = (bcc, rows) => run('send', 'Prepare Recipients', { input: [], refs: { 'Validate Send': [{ ...v, bcc_email: bcc }], 'Get Staged Candidates': rows, 'Get Recently Sent': [] } });
  const out = prep('me@n8n.io', [{ id: 1, email: 'a@x.io', first_name: ' Ada ' }, { id: 2, email: 'b@x.io', first_name: '  ' }, { id: 3, email: 'c@x.io' }]);
  assert('BCC on every item', same(out.map(o => o.bcc), ['me@n8n.io', 'me@n8n.io', 'me@n8n.io']));
  assert('Name trimmed', out[0].body.endsWith('Hi Ada,'));
  assert('Blank or missing name falls back to there', out[1].body.endsWith('Hi there,') && out[2].body.endsWith('Hi there,'));
  assert('No bcc gives an empty value', same(prep('', [{ id: 1, email: 'a@x.io', first_name: 'Ada' }]).map(o => o.bcc), ['']));
});

