  for (const excludeRecentDays of [null, '', 0, -1, false]) assert('Invalid value ' + JSON.stringify(excludeRecentDays) + ' gives 60', run('search', 'Normalize Input', { refs: { 'When Called': [{ excludeRecentDays }], 'Load Config': [{ cooldownDays: 60 }] } })[0].excludeRecentDays === 60);
});
