check('Search: fails safe when the duplicate check cannot run', assert => {
  const unread = format([{ email }, { email, sibling: true, fetchError: true }]);
  assert('Unreadable twin skips the person', unread.candidates.length === 0 && unread.duplicateCheckFailed === 1);
  const failed = format([{ email }], { lookupStatus: 500 });
  assert('Failed lookup fails the search', failed.candidates.length === 0 && /duplicate-profile check failed/.test(failed.error || ''));
  const gone = format([{ email: 'ok@example.test' }, { email: 'gone@example.test', sibling: true, uploaded: true, fetchError: true, inCooldownSegment: true }]);
  assert('Twins of emails the search did not return are not read', gone.candidates.length === 1 && gone.duplicateCheckFailed === 0);
