check('Search: who represents a person with several profiles', assert => {
  assert('The subscribed profile, not the unsubscribed one', format([{ email, unsubscribed: true, first_name: 'Unsub' }, { email, first_name: 'Good' }]).candidates[0].first_name === 'Good');
