  assert('People keep their sample order', same(format([{ email: 'b@example.test' }, { email: 'a@example.test', first_name: 'A', cloud_plan: 'Cloud Pro-1' }]).candidates.map(c => c.email), ['b@example.test', 'a@example.test']));
});
check('Search: numbers reported for the card', assert => {
  assert('Profiles per email', same(format([{ email }, { email, sibling: true }, { email, sibling: true }]).csvStats.duplicateProfileEmails, [{ email, profileCount: 3 }]));
  const out = format([{ email: 'ok@example.test' }, { email: 'twin-cooldown@example.test' }, { email: 'twin-cooldown@example.test', sibling: true, inCooldownSegment: true }, { email: 'unsub@example.test', unsubscribed: true }, { email: 'all-cooldown@example.test', sibling: true, uploaded: true, inCooldownSegment: true }], { extraUploaded: ['nobody@example.test'] });
  const cs = out.csvStats;
  assert('CSV breakdown adds up', same([cs.total, out.candidates.length, cs.skippedCooldown, cs.skippedUnsubscribed, cs.skippedNotFound, cs.skippedOther, cs.overCap], [5, 1, 2, 1, 1, 0, 0]));
  const capped = format([{ email: 'a@example.test' }, { email: 'b@example.test' }, { email: 'c@example.test' }], { sampleSize: 2 });
  assert('People over the cap are not counted as skipped', same([capped.candidates.length, capped.csvStats.overCap, capped.csvStats.skippedOther], [2, 1, 0]));
  const users = format([{ email: 'a@example.test' }, { email: 'a@example.test', unsubscribed: true, sibling: true }, { email: 'b@example.test' }, { email: 'b@example.test', sibling: true, inCooldownSegment: true }], { mode: 'n8n_users' });
  assert('n8n users: people counts and mixed-status list', same([users.peopleSkippedCooldown, users.peopleSkippedUnsubscribed, users.unsubscribeConflictEmails], [1, 0, ['a@example.test']]));
  const labelled = format([{ email }], { mode: 'n8n_users', filters: { wf_bucket: ['100+', 'unknown'], other: 'x' }, extraConfig: { nUserFilters: [{ id: 'wf_bucket', label: 'Production workflows', options: [{ value: '100+', label: '100+ (~18k)' }] }] } });
  assert('Filters come back with their Config labels', same(labelled.filterLabels, [{ label: 'Production workflows', values: ['100+ (~18k)', 'unknown'] }, { label: 'other', values: ['x'] }]));
